INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'ledger-create-save', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'ledger-create-save'), 0) + 1, '{"answer":0,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 1  | ユナ | 東通り\n// 2  | オル | 西通り\n// 3  | ミナ | 東通り\n$villager = new Villager();\n$villager->name = ''ソラ'';\n$villager->address = ''南通り'';\n$villager->save();\n// id は自動採番、他の必須列はない。","difficulty":"intermediate","explanation":"new Villager は新規モデルを作り、その save は新しい行を追加する。既存行を取得していないため id=1 の更新ではなく、全行更新でもない。save まで実行した点も確認しよう。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-create-save","kind":"choice","options":["ソラの行が追加され、合計4行になる","id=1 の名前だけがソラになる","全員の住所が南通りになる","保存されず3行のままになる"],"prompt":"3人の名簿に対し、このコードを正常に実行した結果は？","reveal":"ソラの行が追加され、合計4行になる","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'ledger-create-save' AND payload_json = '{"answer":0,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 1  | ユナ | 東通り\n// 2  | オル | 西通り\n// 3  | ミナ | 東通り\n$villager = new Villager();\n$villager->name = ''ソラ'';\n$villager->address = ''南通り'';\n$villager->save();\n// id は自動採番、他の必須列はない。","difficulty":"intermediate","explanation":"new Villager は新規モデルを作り、その save は新しい行を追加する。既存行を取得していないため id=1 の更新ではなく、全行更新でもない。save まで実行した点も確認しよう。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-create-save","kind":"choice","options":["ソラの行が追加され、合計4行になる","id=1 の名前だけがソラになる","全員の住所が南通りになる","保存されず3行のままになる"],"prompt":"3人の名簿に対し、このコードを正常に実行した結果は？","reveal":"ソラの行が追加され、合計4行になる","topic":"laravel"}');
