INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'ledger-create-unpersisted', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'ledger-create-unpersisted'), 0) + 1, '{"answer":2,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 1  | ユナ | 東通り\n// 2  | オル | 西通り\n// 3  | ミナ | 東通り\n$villager = new Villager();\n$villager->name = ''ソラ'';\n$villager->address = ''南通り'';\n// save はまだ呼んでいない。","difficulty":"intermediate","explanation":"new とプロパティへの代入だけではDBへの書き込みは起きない。save して初めて新規行が保存される。オブジェクトを作ることと永続化を分けて考えよう。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-create-unpersisted","kind":"choice","options":["name の代入で追加されている","address の代入で追加されている","このコードでは追加されていない","new の時点で追加されている"],"prompt":"この時点でDBにソラの行はある？","reveal":"このコードでは追加されていない","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'ledger-create-unpersisted' AND payload_json = '{"answer":2,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 1  | ユナ | 東通り\n// 2  | オル | 西通り\n// 3  | ミナ | 東通り\n$villager = new Villager();\n$villager->name = ''ソラ'';\n$villager->address = ''南通り'';\n// save はまだ呼んでいない。","difficulty":"intermediate","explanation":"new とプロパティへの代入だけではDBへの書き込みは起きない。save して初めて新規行が保存される。オブジェクトを作ることと永続化を分けて考えよう。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-create-unpersisted","kind":"choice","options":["name の代入で追加されている","address の代入で追加されている","このコードでは追加されていない","new の時点で追加されている"],"prompt":"この時点でDBにソラの行はある？","reveal":"このコードでは追加されていない","topic":"laravel"}');
