INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'ledger-create-validate', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'ledger-create-validate'), 0) + 1, '{"answer":1,"code":"// コントローラ内。$request は受け取ったリクエスト。\n$data = $request->validate([\n    ''name'' => [''required'', ''string''],\n    ''address'' => [''required'', ''string''],\n]);\n$villager = new Villager();\n$villager->name = $data[''name''];\n$villager->address = $data[''address''];\n$villager->save();","difficulty":"intermediate","explanation":"required は空文字の名前を受理しない。validate が失敗すると後ろの save には進まないため、一部だけの保存も起きない。このコードには既存行を更新する処理もない。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-create-validate","kind":"choice","options":["既存の全員の名前が空になる","検証で失敗するため、追加されない","空の名前の行が追加される","住所だけの行が追加される"],"prompt":"Laravel のリクエストで name が空文字。この処理で新しい行は追加される？","reveal":"検証で失敗するため、追加されない","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'ledger-create-validate' AND payload_json = '{"answer":1,"code":"// コントローラ内。$request は受け取ったリクエスト。\n$data = $request->validate([\n    ''name'' => [''required'', ''string''],\n    ''address'' => [''required'', ''string''],\n]);\n$villager = new Villager();\n$villager->name = $data[''name''];\n$villager->address = $data[''address''];\n$villager->save();","difficulty":"intermediate","explanation":"required は空文字の名前を受理しない。validate が失敗すると後ろの save には進まないため、一部だけの保存も起きない。このコードには既存行を更新する処理もない。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-create-validate","kind":"choice","options":["既存の全員の名前が空になる","検証で失敗するため、追加されない","空の名前の行が追加される","住所だけの行が追加される"],"prompt":"Laravel のリクエストで name が空文字。この処理で新しい行は追加される？","reveal":"検証で失敗するため、追加されない","topic":"laravel"}');
