INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'ledger-create-vs-schema', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'ledger-create-vs-schema'), 0) + 1, '{"answer":3,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 1  | ユナ | 東通り\n// 2  | オル | 西通り\n// 3  | ミナ | 東通り\n","difficulty":"intermediate","explanation":"テーブルの構造はすでに足りているので、新規モデルの保存で行を追加する。マイグレーションは列などの構造変更、全行 update は既存データの変更。テーブルの作り直しは既存の名簿を失うおそれがある。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-create-vs-schema","kind":"choice","options":["名前用の列を増やすマイグレーションを作る","既存の全行の名前をソラに update する","villagers テーブルを作り直す","新規モデルに名前と住所を入れて save する"],"prompt":"villagers テーブルはすでにある。ソラの行を1件登録するために必要なのは？","reveal":"新規モデルに名前と住所を入れて save する","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'ledger-create-vs-schema' AND payload_json = '{"answer":3,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 1  | ユナ | 東通り\n// 2  | オル | 西通り\n// 3  | ミナ | 東通り\n","difficulty":"intermediate","explanation":"テーブルの構造はすでに足りているので、新規モデルの保存で行を追加する。マイグレーションは列などの構造変更、全行 update は既存データの変更。テーブルの作り直しは既存の名簿を失うおそれがある。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-create-vs-schema","kind":"choice","options":["名前用の列を増やすマイグレーションを作る","既存の全行の名前をソラに update する","villagers テーブルを作り直す","新規モデルに名前と住所を入れて save する"],"prompt":"villagers テーブルはすでにある。ソラの行を1件登録するために必要なのは？","reveal":"新規モデルに名前と住所を入れて save する","topic":"laravel"}');
