INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'ledger-delete-preview', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'ledger-delete-preview'), 0) + 1, '{"answer":2,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 7  | ソラ | 南通り\n// 8  | ソラ | 南通り\n// 9  | ミナ | 東通り\n// 控えと照合済み。id=8 だけが誤登録。\n","difficulty":"intermediate","explanation":"find(8) は対象を読み取るだけなので削除前の照合に使える。delete は確認前の削除、update は住所の書き換え、条件なしの delete は全行削除になる。読み取りと書き込みを区別しよう。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-delete-preview","kind":"choice","options":["Villager::where(''id'', 8)->update([''address'' => ''北通り''])","Villager::query()->delete()","Villager::find(8)","Villager::where(''id'', 8)->delete()"],"prompt":"まだ削除はしない。削除予定の id=8 の中身だけを確認する操作は？","reveal":"Villager::find(8)","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'ledger-delete-preview' AND payload_json = '{"answer":2,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 7  | ソラ | 南通り\n// 8  | ソラ | 南通り\n// 9  | ミナ | 東通り\n// 控えと照合済み。id=8 だけが誤登録。\n","difficulty":"intermediate","explanation":"find(8) は対象を読み取るだけなので削除前の照合に使える。delete は確認前の削除、update は住所の書き換え、条件なしの delete は全行削除になる。読み取りと書き込みを区別しよう。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-delete-preview","kind":"choice","options":["Villager::where(''id'', 8)->update([''address'' => ''北通り''])","Villager::query()->delete()","Villager::find(8)","Villager::where(''id'', 8)->delete()"],"prompt":"まだ削除はしない。削除予定の id=8 の中身だけを確認する操作は？","reveal":"Villager::find(8)","topic":"laravel"}');
