INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'ledger-delete-result', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'ledger-delete-result'), 0) + 1, '{"answer":1,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 7  | ソラ | 南通り\n// 8  | ソラ | 南通り\n// 9  | ミナ | 東通り\n// 控えと照合済み。id=8 だけが誤登録。\nVillager::where(''id'', 8)->delete();\n// SoftDeletes は使っていない。","difficulty":"intermediate","explanation":"id=8 だけを条件にしているので、残るのは id=7 と9。8と9なら消す対象の取り違え、9だけなら名前でまとめて消した場合。SoftDeletes を使わない前提なので、8はDBから削除される。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-delete-result","kind":"choice","options":["7・8・9 すべて","7 と 9","8 と 9","9 だけ"],"prompt":"この削除が正常に終わったあと、残る id は？","reveal":"7 と 9","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'ledger-delete-result' AND payload_json = '{"answer":1,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 7  | ソラ | 南通り\n// 8  | ソラ | 南通り\n// 9  | ミナ | 東通り\n// 控えと照合済み。id=8 だけが誤登録。\nVillager::where(''id'', 8)->delete();\n// SoftDeletes は使っていない。","difficulty":"intermediate","explanation":"id=8 だけを条件にしているので、残るのは id=7 と9。8と9なら消す対象の取り違え、9だけなら名前でまとめて消した場合。SoftDeletes を使わない前提なので、8はDBから削除される。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-delete-result","kind":"choice","options":["7・8・9 すべて","7 と 9","8 と 9","9 だけ"],"prompt":"この削除が正常に終わったあと、残る id は？","reveal":"7 と 9","topic":"laravel"}');
