INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'ledger-delete-transfer', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'ledger-delete-transfer'), 0) + 1, '{"answer":3,"code":"// サインイン済みユーザーの掲示板。\n// 投稿には id と user_id（投稿者ID）がある。\n// 編集者・管理者の特別権限はない。\n// 画面から送られた投稿IDは変更され得る。","difficulty":"intermediate","explanation":"存在確認だけでは他人の投稿も消せてしまう。画面の表示や送信値は書き換えられるので、サーバーで対象を特定し、信頼できるログイン情報と投稿の user_id を照合して削除を許可する。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-delete-transfer","kind":"choice","options":["投稿IDが存在することだけ","削除ボタンが画面に表示されていたことだけ","リクエストに投稿者IDが入っていることだけ","対象の投稿IDと、ログイン中の利用者がその投稿者であること"],"prompt":"掲示板で「自分の投稿1件だけ」を削除する。サーバーで最低限確認したい組み合わせは？","reveal":"対象の投稿IDと、ログイン中の利用者がその投稿者であること","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'ledger-delete-transfer' AND payload_json = '{"answer":3,"code":"// サインイン済みユーザーの掲示板。\n// 投稿には id と user_id（投稿者ID）がある。\n// 編集者・管理者の特別権限はない。\n// 画面から送られた投稿IDは変更され得る。","difficulty":"intermediate","explanation":"存在確認だけでは他人の投稿も消せてしまう。画面の表示や送信値は書き換えられるので、サーバーで対象を特定し、信頼できるログイン情報と投稿の user_id を照合して削除を許可する。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-delete-transfer","kind":"choice","options":["投稿IDが存在することだけ","削除ボタンが画面に表示されていたことだけ","リクエストに投稿者IDが入っていることだけ","対象の投稿IDと、ログイン中の利用者がその投稿者であること"],"prompt":"掲示板で「自分の投稿1件だけ」を削除する。サーバーで最低限確認したい組み合わせは？","reveal":"対象の投稿IDと、ログイン中の利用者がその投稿者であること","topic":"laravel"}');
