INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'ledger-read-filter', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'ledger-read-filter'), 0) + 1, '{"answer":0,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 1  | ユナ | 東通り\n// 2  | オル | 西通り\n// 3  | ミナ | 東通り\n$villagers = Villager::where(''address'', ''東通り'')->get();","difficulty":"intermediate","explanation":"where は住所が東通りの行に絞り、get は該当する全行を取得する。first なら最初の1件だけになる。西通りのオルは条件外であり、全員を取得する処理でもない。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-read-filter","kind":"choice","options":["ユナとミナ","ユナだけ","オルだけ","ユナ・オル・ミナ全員"],"prompt":"この取得結果に含まれる村人は誰？","reveal":"ユナとミナ","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'ledger-read-filter' AND payload_json = '{"answer":0,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 1  | ユナ | 東通り\n// 2  | オル | 西通り\n// 3  | ミナ | 東通り\n$villagers = Villager::where(''address'', ''東通り'')->get();","difficulty":"intermediate","explanation":"where は住所が東通りの行に絞り、get は該当する全行を取得する。first なら最初の1件だけになる。西通りのオルは条件外であり、全員を取得する処理でもない。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-read-filter","kind":"choice","options":["ユナとミナ","ユナだけ","オルだけ","ユナ・オル・ミナ全員"],"prompt":"この取得結果に含まれる村人は誰？","reveal":"ユナとミナ","topic":"laravel"}');
