INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'ledger-read-id', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'ledger-read-id'), 0) + 1, '{"answer":1,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 1  | ユナ | 東通り\n// 2  | オル | 西通り\n// 3  | ミナ | 東通り\n","difficulty":"intermediate","explanation":"find は主キーで1件を探す。all は全件、住所の where は住所が一致する複数件、count は人数を返す。同じ名前の人がいても、主キーで区別できる。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-read-id","kind":"choice","options":["Villager::count()","Villager::find(2)","Villager::all()","Villager::where(''address'', ''東通り'')->get()"],"prompt":"id=2 の1人を取得するコードはどれ？","reveal":"Villager::find(2)","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'ledger-read-id' AND payload_json = '{"answer":1,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 1  | ユナ | 東通り\n// 2  | オル | 西通り\n// 3  | ミナ | 東通り\n","difficulty":"intermediate","explanation":"find は主キーで1件を探す。all は全件、住所の where は住所が一致する複数件、count は人数を返す。同じ名前の人がいても、主キーで区別できる。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-read-id","kind":"choice","options":["Villager::count()","Villager::find(2)","Villager::all()","Villager::where(''address'', ''東通り'')->get()"],"prompt":"id=2 の1人を取得するコードはどれ？","reveal":"Villager::find(2)","topic":"laravel"}');
