INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'ledger-read-missing', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'ledger-read-missing'), 0) + 1, '{"answer":2,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 1  | ユナ | 東通り\n// 2  | オル | 西通り\n// 3  | ミナ | 東通り\n$villager = Villager::find(99);\nif ($villager === null) {\n    return ''見つかりません'';\n}\nreturn $villager->name;","difficulty":"intermediate","explanation":"find は見つからないと null を返すため、この分岐に入る。空文字の村人や先頭の村人を返す処理でも、自動作成する処理でもない。存在を確認してから名前を読む。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-read-missing","kind":"choice","options":["ユナ","99番の村人が自動で登録される","見つかりません","空の名前"],"prompt":"該当する行がない。この分岐で返る文字列は？","reveal":"見つかりません","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'ledger-read-missing' AND payload_json = '{"answer":2,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 1  | ユナ | 東通り\n// 2  | オル | 西通り\n// 3  | ミナ | 東通り\n$villager = Villager::find(99);\nif ($villager === null) {\n    return ''見つかりません'';\n}\nreturn $villager->name;","difficulty":"intermediate","explanation":"find は見つからないと null を返すため、この分岐に入る。空文字の村人や先頭の村人を返す処理でも、自動作成する処理でもない。存在を確認してから名前を読む。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-read-missing","kind":"choice","options":["ユナ","99番の村人が自動で登録される","見つかりません","空の名前"],"prompt":"該当する行がない。この分岐で返る文字列は？","reveal":"見つかりません","topic":"laravel"}');
