INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'ledger-read-no-write', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'ledger-read-no-write'), 0) + 1, '{"answer":3,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 1  | ユナ | 東通り\n// 2  | オル | 西通り\n// 3  | ミナ | 東通り\n$villagers = Villager::where(''address'', ''東通り'')->get();","difficulty":"intermediate","explanation":"where と get は読み取りの条件と取得を行う。条件外の行を削除するには delete、新規行には保存、住所変更には update などの書き込みが必要じゃ。検索結果とDB本体は区別しよう。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-read-no-write","kind":"choice","options":["東通りの2行だけ残る","東通りの2行が新しく追加される","3行とも住所が東通りに変わる","3行のまま、各行の内容も変わらない"],"prompt":"読み取りだけを実行したあと、DBの名簿はどうなる？","reveal":"3行のまま、各行の内容も変わらない","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'ledger-read-no-write' AND payload_json = '{"answer":3,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 1  | ユナ | 東通り\n// 2  | オル | 西通り\n// 3  | ミナ | 東通り\n$villagers = Villager::where(''address'', ''東通り'')->get();","difficulty":"intermediate","explanation":"where と get は読み取りの条件と取得を行う。条件外の行を削除するには delete、新規行には保存、住所変更には update などの書き込みが必要じゃ。検索結果とDB本体は区別しよう。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-read-no-write","kind":"choice","options":["東通りの2行だけ残る","東通りの2行が新しく追加される","3行とも住所が東通りに変わる","3行のまま、各行の内容も変わらない"],"prompt":"読み取りだけを実行したあと、DBの名簿はどうなる？","reveal":"3行のまま、各行の内容も変わらない","topic":"laravel"}');
