INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'ledger-update-count', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'ledger-update-count'), 0) + 1, '{"answer":3,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 1  | ユナ | 東通り\n// 2  | オル | 西通り\n// 3  | ミナ | 東通り\n$villager = Villager::findOrFail(2);\n$villager->address = ''北通り'';\n$villager->save();","difficulty":"intermediate","explanation":"既存行の更新は値を変えるだけで行数を変えない。2行なら削除、4行なら追加、0行なら全削除などが起きたことになる。行数だけで住所の正しさまでは確認できないので、変更した値も読み直そう。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-update-count","kind":"choice","options":["2行","4行","0行","3行"],"prompt":"正常に住所を修正したあと、名簿の行数は？","reveal":"3行","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'ledger-update-count' AND payload_json = '{"answer":3,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 1  | ユナ | 東通り\n// 2  | オル | 西通り\n// 3  | ミナ | 東通り\n$villager = Villager::findOrFail(2);\n$villager->address = ''北通り'';\n$villager->save();","difficulty":"intermediate","explanation":"既存行の更新は値を変えるだけで行数を変えない。2行なら削除、4行なら追加、0行なら全削除などが起きたことになる。行数だけで住所の正しさまでは確認できないので、変更した値も読み直そう。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-update-count","kind":"choice","options":["2行","4行","0行","3行"],"prompt":"正常に住所を修正したあと、名簿の行数は？","reveal":"3行","topic":"laravel"}');
