INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'ledger-update-save', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'ledger-update-save'), 0) + 1, '{"answer":1,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 1  | ユナ | 東通り\n// 2  | オル | 西通り\n// 3  | ミナ | 東通り\n$villager = Villager::findOrFail(1);\n$villager->address = ''北通り'';\n// ここで処理終了。save は呼んでいない。","difficulty":"intermediate","explanation":"代入で変わるのは取得したモデルのメモリ上の値。save していないためDBには元の東通りが残る。値の代入は、空欄への更新でも削除でもない。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-update-save","kind":"choice","options":["id=1 の行がなくなる","東通り","北通り","空欄"],"prompt":"このコードだけを実行した直後、DBに保存されている id=1 の住所は？","reveal":"東通り","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'ledger-update-save' AND payload_json = '{"answer":1,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 1  | ユナ | 東通り\n// 2  | オル | 西通り\n// 3  | ミナ | 東通り\n$villager = Villager::findOrFail(1);\n$villager->address = ''北通り'';\n// ここで処理終了。save は呼んでいない。","difficulty":"intermediate","explanation":"代入で変わるのは取得したモデルのメモリ上の値。save していないためDBには元の東通りが残る。値の代入は、空欄への更新でも削除でもない。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-update-save","kind":"choice","options":["id=1 の行がなくなる","東通り","北通り","空欄"],"prompt":"このコードだけを実行した直後、DBに保存されている id=1 の住所は？","reveal":"東通り","topic":"laravel"}');
