INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'ledger-update-scope', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'ledger-update-scope'), 0) + 1, '{"answer":2,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 1  | ユナ | 東通り\n// 2  | オル | 西通り\n// 3  | ミナ | 東通り\n","difficulty":"intermediate","explanation":"id の条件で対象を1行に絞って update する。条件なしの update は全行、住所の条件ではユナとミナが対象になる。delete は住所修正ではなく行の削除じゃ。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-update-scope","kind":"choice","options":["Villager::where(''address'', ''東通り'')->update([''address'' => ''北通り''])","Villager::where(''id'', 2)->delete()","Villager::where(''id'', 2)->update([''address'' => ''北通り''])","Villager::query()->update([''address'' => ''北通り''])"],"prompt":"id=2 の住所だけを直したい。条件に合うコードはどれ？","reveal":"Villager::where(''id'', 2)->update([''address'' => ''北通り''])","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'ledger-update-scope' AND payload_json = '{"answer":2,"code":"// villagers テーブル（id は主キー）\n// id | name | address\n// 1  | ユナ | 東通り\n// 2  | オル | 西通り\n// 3  | ミナ | 東通り\n","difficulty":"intermediate","explanation":"id の条件で対象を1行に絞って update する。条件なしの update は全行、住所の条件ではユナとミナが対象になる。delete は住所修正ではなく行の削除じゃ。","filename":"名簿の実習 / Laravel Eloquent","id":"ledger-update-scope","kind":"choice","options":["Villager::where(''address'', ''東通り'')->update([''address'' => ''北通り''])","Villager::where(''id'', 2)->delete()","Villager::where(''id'', 2)->update([''address'' => ''北通り''])","Villager::query()->update([''address'' => ''北通り''])"],"prompt":"id=2 の住所だけを直したい。条件に合うコードはどれ？","reveal":"Villager::where(''id'', 2)->update([''address'' => ''北通り''])","topic":"laravel"}');
