INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'resource-create-redirect-only', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'resource-create-redirect-only'), 0) + 1, '{"answer":0,"code":"public function store(Request $request)\n{\n    return redirect(''/villagers'');\n}","difficulty":"intermediate","explanation":"storeというメソッド名、POSTというHTTPメソッド、redirectのどれにも自動保存の働きはない。入力検証とモデルの保存を実装する必要がある。画面遷移に成功しても、DB保存の成功とは限らない。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-create-redirect-only","kind":"choice","options":["保存されない。新規モデルの保存処理がない","storeという名前なので自動で保存される","リダイレクト先で自動で保存される","POSTなのでLaravelが全入力を自動で保存する"],"prompt":"フォームから送信し一覧へ戻れた。この実装だけで新規行は保存される？","reveal":"保存されない。新規モデルの保存処理がない","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'resource-create-redirect-only' AND payload_json = '{"answer":0,"code":"public function store(Request $request)\n{\n    return redirect(''/villagers'');\n}","difficulty":"intermediate","explanation":"storeというメソッド名、POSTというHTTPメソッド、redirectのどれにも自動保存の働きはない。入力検証とモデルの保存を実装する必要がある。画面遷移に成功しても、DB保存の成功とは限らない。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-create-redirect-only","kind":"choice","options":["保存されない。新規モデルの保存処理がない","storeという名前なので自動で保存される","リダイレクト先で自動で保存される","POSTなのでLaravelが全入力を自動で保存する"],"prompt":"フォームから送信し一覧へ戻れた。この実装だけで新規行は保存される？","reveal":"保存されない。新規モデルの保存処理がない","topic":"laravel"}');
