INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'resource-create-store-flow', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'resource-create-store-flow'), 0) + 1, '{"answer":2,"code":"$data = $request->validate([\n    ''name'' => [''required'', ''string''],\n    ''address'' => [''required'', ''string''],\n]);\n$villager = new Villager();\n$villager->name = $data[''name''];\n$villager->address = $data[''address''];\n$villager->save();\nreturn redirect(''/villagers'');","difficulty":"intermediate","explanation":"検証済みの値を新規モデルへ入れ、saveで追加してからredirectする。redirectだけの処理とは違いsaveがある。既存行への代入やdeleteはないため、既存3行は残る。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-create-store-flow","kind":"choice","options":["一覧へ移動するだけで、新規行は保存されない","既存の全員がソラに書き換わる","ソラが1行追加され、一覧への移動先が返る","ソラが1行追加され、既存3行は消える"],"prompt":"name=ソラ、address=南通りを送信。この処理の結果は？","reveal":"ソラが1行追加され、一覧への移動先が返る","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'resource-create-store-flow' AND payload_json = '{"answer":2,"code":"$data = $request->validate([\n    ''name'' => [''required'', ''string''],\n    ''address'' => [''required'', ''string''],\n]);\n$villager = new Villager();\n$villager->name = $data[''name''];\n$villager->address = $data[''address''];\n$villager->save();\nreturn redirect(''/villagers'');","difficulty":"intermediate","explanation":"検証済みの値を新規モデルへ入れ、saveで追加してからredirectする。redirectだけの処理とは違いsaveがある。既存行への代入やdeleteはないため、既存3行は残る。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-create-store-flow","kind":"choice","options":["一覧へ移動するだけで、新規行は保存されない","既存の全員がソラに書き換わる","ソラが1行追加され、一覧への移動先が返る","ソラが1行追加され、既存3行は消える"],"prompt":"name=ソラ、address=南通りを送信。この処理の結果は？","reveal":"ソラが1行追加され、一覧への移動先が返る","topic":"laravel"}');
