INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'resource-create-validation-scope', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'resource-create-validation-scope'), 0) + 1, '{"answer":3,"code":"$data = $request->validate([\n    ''name'' => [''required'', ''string''],\n    ''address'' => [''required'', ''string''],\n]);\n// ここまで。まだ保存していない。","difficulty":"intermediate","explanation":"このvalidateにルールがあるのはnameとaddressなので、検証済み配列はその二項目。余分なis_adminが権限情報として保証されることはなく、idも自動で検証結果へ追加されない。検証と操作権限の確認は別の仕事。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-create-validation-scope","kind":"choice","options":["送信された name・address・is_admin の全部","is_admin だけ","id だけが自動で入る","name と address"],"prompt":"name・addressに加え、is_admin=true が送られた。この $data に入る項目は？","reveal":"name と address","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'resource-create-validation-scope' AND payload_json = '{"answer":3,"code":"$data = $request->validate([\n    ''name'' => [''required'', ''string''],\n    ''address'' => [''required'', ''string''],\n]);\n// ここまで。まだ保存していない。","difficulty":"intermediate","explanation":"このvalidateにルールがあるのはnameとaddressなので、検証済み配列はその二項目。余分なis_adminが権限情報として保証されることはなく、idも自動で検証結果へ追加されない。検証と操作権限の確認は別の仕事。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-create-validation-scope","kind":"choice","options":["送信された name・address・is_admin の全部","is_admin だけ","id だけが自動で入る","name と address"],"prompt":"name・addressに加え、is_admin=true が送られた。この $data に入る項目は？","reveal":"name と address","topic":"laravel"}');
