INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'resource-delete-authorization', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'resource-delete-authorization'), 0) + 1, '{"answer":0,"code":"// ルートの対象 id=8 は見つかった。\n// まだ削除・認可は行っていない。","difficulty":"intermediate","explanation":"モデルが存在しても削除する権限があるとは限らない。サーバーで認証済み利用者とポリシー等のルールを照合する。ボタンの表示や送信された権限値は書き換えられるため、許可の根拠にならない。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-delete-authorization","kind":"choice","options":["ログイン中の利用者に、その対象を削除する権限があるか確認する","id=8が存在するので、そのまま削除を許可する","画面に削除ボタンがあったので、そのまま許可する","送られた is_admin=true だけを信頼して許可する"],"prompt":"id=8の取得に成功した。管理者以外もアクセスし得る。サーバーの削除前に必要なのは？","reveal":"ログイン中の利用者に、その対象を削除する権限があるか確認する","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'resource-delete-authorization' AND payload_json = '{"answer":0,"code":"// ルートの対象 id=8 は見つかった。\n// まだ削除・認可は行っていない。","difficulty":"intermediate","explanation":"モデルが存在しても削除する権限があるとは限らない。サーバーで認証済み利用者とポリシー等のルールを照合する。ボタンの表示や送信された権限値は書き換えられるため、許可の根拠にならない。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-delete-authorization","kind":"choice","options":["ログイン中の利用者に、その対象を削除する権限があるか確認する","id=8が存在するので、そのまま削除を許可する","画面に削除ボタンがあったので、そのまま許可する","送られた is_admin=true だけを信頼して許可する"],"prompt":"id=8の取得に成功した。管理者以外もアクセスし得る。サーバーの削除前に必要なのは？","reveal":"ログイン中の利用者に、その対象を削除する権限があるか確認する","topic":"laravel"}');
