INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'resource-delete-confirmation', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'resource-delete-confirmation'), 0) + 1, '{"answer":2,"difficulty":"intermediate","explanation":"確認は読み取り。実際の削除には対象IDのDELETEとサーバーでの認可・削除が必要。画面から隠すだけではDBは変わらず、照合前の同名一括削除では正しい行も失う。","id":"resource-delete-confirmation","kind":"choice","options":["showを表示した時点で削除済みと扱う","画面側で行を隠すだけでDBも削除済みと扱う","DELETEで対象IDを送り、サーバーで認可してから対象を削除する","名前が同じ行をすべて削除してから対象を照合する"],"prompt":"show画面で誤登録だと確認した。対象だけ削除するために、その後必要な流れは？","reveal":"DELETEで対象IDを送り、サーバーで認可してから対象を削除する","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'resource-delete-confirmation' AND payload_json = '{"answer":2,"difficulty":"intermediate","explanation":"確認は読み取り。実際の削除には対象IDのDELETEとサーバーでの認可・削除が必要。画面から隠すだけではDBは変わらず、照合前の同名一括削除では正しい行も失う。","id":"resource-delete-confirmation","kind":"choice","options":["showを表示した時点で削除済みと扱う","画面側で行を隠すだけでDBも削除済みと扱う","DELETEで対象IDを送り、サーバーで認可してから対象を削除する","名前が同じ行をすべて削除してから対象を照合する"],"prompt":"show画面で誤登録だと確認した。対象だけ削除するために、その後必要な流れは？","reveal":"DELETEで対象IDを送り、サーバーで認可してから対象を削除する","topic":"laravel"}');
