INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'resource-delete-get-safe', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'resource-delete-get-safe'), 0) + 1, '{"answer":3,"code":"Route::resource(''villagers'', VillagerController::class);","difficulty":"intermediate","explanation":"このGETは詳細のshow。読み取りだけでDELETEのdestroyは呼ばれない。対象の削除、同名全行の削除、名前の更新を行うコードはないので、DBは変化しない。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-delete-get-safe","kind":"choice","options":["id=8だけが削除され2行になる","同名のソラが2行とも削除される","id=8の名前が空に変更される","id=8を含む3行がそのまま残る"],"prompt":"通常のresourceで GET /villagers/8 を開いた。削除コードはない。この時点のDBは？","reveal":"id=8を含む3行がそのまま残る","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'resource-delete-get-safe' AND payload_json = '{"answer":3,"code":"Route::resource(''villagers'', VillagerController::class);","difficulty":"intermediate","explanation":"このGETは詳細のshow。読み取りだけでDELETEのdestroyは呼ばれない。対象の削除、同名全行の削除、名前の更新を行うコードはないので、DBは変化しない。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-delete-get-safe","kind":"choice","options":["id=8だけが削除され2行になる","同名のソラが2行とも削除される","id=8の名前が空に変更される","id=8を含む3行がそのまま残る"],"prompt":"通常のresourceで GET /villagers/8 を開いた。削除コードはない。この時点のDBは？","reveal":"id=8を含む3行がそのまま残る","topic":"laravel"}');
