INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'resource-delete-http', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'resource-delete-http'), 0) + 1, '{"answer":2,"difficulty":"beginner","explanation":"DELETEと対象IDがdestroyに対応する。GETのshowは閲覧、PATCHのupdateは既存値の変更、POSTのstoreは新規保存。表示するリクエストを削除の意味で扱わない。","id":"resource-delete-http","kind":"choice","options":["GET /villagers/8 → show","PATCH /villagers/8 → update","DELETE /villagers/8 → destroy","POST /villagers → store"],"prompt":"照合済みの誤登録id=8を削除処理へ送る。標準の対応は？","reveal":"DELETE /villagers/8 → destroy","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'resource-delete-http' AND payload_json = '{"answer":2,"difficulty":"beginner","explanation":"DELETEと対象IDがdestroyに対応する。GETのshowは閲覧、PATCHのupdateは既存値の変更、POSTのstoreは新規保存。表示するリクエストを削除の意味で扱わない。","id":"resource-delete-http","kind":"choice","options":["GET /villagers/8 → show","PATCH /villagers/8 → update","DELETE /villagers/8 → destroy","POST /villagers → store"],"prompt":"照合済みの誤登録id=8を削除処理へ送る。標準の対応は？","reveal":"DELETE /villagers/8 → destroy","topic":"laravel"}');
