INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'resource-delete-redirect', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'resource-delete-redirect'), 0) + 1, '{"answer":1,"code":"public function destroy(Villager $villager)\n{\n    // 認可済み。SoftDeletesは使わない。\n    $villager->delete();\n    return redirect(''/villagers'');\n}","difficulty":"intermediate","explanation":"受け取ったid=8のモデルだけdeleteする。redirectは画面の移動先を返すが、削除を取り消したり同名の行まで消したりしない。条件なしで全行を削除するコードでもない。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-delete-redirect","kind":"choice","options":["id=7・8・9が残り、一覧への移動先が返る","id=7と9が残り、一覧への移動先が返る","id=9だけが残り、一覧への移動先が返る","全行が削除され、一覧への移動先が返る"],"prompt":"id=8のモデルを受け取った。この実装後のDBと画面の動きは？","reveal":"id=7と9が残り、一覧への移動先が返る","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'resource-delete-redirect' AND payload_json = '{"answer":1,"code":"public function destroy(Villager $villager)\n{\n    // 認可済み。SoftDeletesは使わない。\n    $villager->delete();\n    return redirect(''/villagers'');\n}","difficulty":"intermediate","explanation":"受け取ったid=8のモデルだけdeleteする。redirectは画面の移動先を返すが、削除を取り消したり同名の行まで消したりしない。条件なしで全行を削除するコードでもない。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-delete-redirect","kind":"choice","options":["id=7・8・9が残り、一覧への移動先が返る","id=7と9が残り、一覧への移動先が返る","id=9だけが残り、一覧への移動先が返る","全行が削除され、一覧への移動先が返る"],"prompt":"id=8のモデルを受け取った。この実装後のDBと画面の動きは？","reveal":"id=7と9が残り、一覧への移動先が返る","topic":"laravel"}');
