INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'resource-delete-transfer', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'resource-delete-transfer'), 0) + 1, '{"answer":3,"code":"$material = Material::findOrFail(42);\n$material->delete();","difficulty":"intermediate","explanation":"findOrFail(42)で取得した1件だけをdeleteするので、id=41は残る。42が残るなら対象を取り違えており、両方残るなら削除していない。全行削除のコードでもない。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-delete-transfer","kind":"choice","options":["id=42の赤い鉱石だけ","id=41と42の両方","どちらも残らない","id=41の青い鉱石だけ"],"prompt":"DELETE /materials/42 で次の処理が成功。残るのは？","reveal":"id=41の青い鉱石だけ","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'resource-delete-transfer' AND payload_json = '{"answer":3,"code":"$material = Material::findOrFail(42);\n$material->delete();","difficulty":"intermediate","explanation":"findOrFail(42)で取得した1件だけをdeleteするので、id=41は残る。42が残るなら対象を取り違えており、両方残るなら削除していない。全行削除のコードでもない。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-delete-transfer","kind":"choice","options":["id=42の赤い鉱石だけ","id=41と42の両方","どちらも残らない","id=41の青い鉱石だけ"],"prompt":"DELETE /materials/42 で次の処理が成功。残るのは？","reveal":"id=41の青い鉱石だけ","topic":"laravel"}');
