INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'resource-read-index-code', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'resource-read-index-code'), 0) + 1, '{"answer":2,"code":"public function index()\n{\n    $villagers = Villager::where(''address'', ''東通り'')->get();\n    return view(''villagers.index'', [''villagers'' => $villagers]);\n}","difficulty":"intermediate","explanation":"where(...)->get() の取得結果を view に渡すので2人が表示対象になる。get は first のような1件取得ではない。view や絞り込みには保存・削除の働きがないため、元のDBは3行のまま。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-read-index-code","kind":"choice","options":["東通りの2人だけをDBに残す","先頭のユナ1人だけを渡し、DBは変えない","東通りの2人を一覧に渡し、DBの全3行は変えない","東通りの2人を新規登録して一覧に渡す"],"prompt":"この処理の表示結果とDBの状態の組み合わせは？","reveal":"東通りの2人を一覧に渡し、DBの全3行は変えない","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'resource-read-index-code' AND payload_json = '{"answer":2,"code":"public function index()\n{\n    $villagers = Villager::where(''address'', ''東通り'')->get();\n    return view(''villagers.index'', [''villagers'' => $villagers]);\n}","difficulty":"intermediate","explanation":"where(...)->get() の取得結果を view に渡すので2人が表示対象になる。get は first のような1件取得ではない。view や絞り込みには保存・削除の働きがないため、元のDBは3行のまま。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-read-index-code","kind":"choice","options":["東通りの2人だけをDBに残す","先頭のユナ1人だけを渡し、DBは変えない","東通りの2人を一覧に渡し、DBの全3行は変えない","東通りの2人を新規登録して一覧に渡す"],"prompt":"この処理の表示結果とDBの状態の組み合わせは？","reveal":"東通りの2人を一覧に渡し、DBの全3行は変えない","topic":"laravel"}');
