INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'resource-read-route', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'resource-read-route'), 0) + 1, '{"answer":1,"code":"Route::resource(''villagers'', VillagerController::class);","difficulty":"intermediate","explanation":"GET /villagers/2 は show。index は番号なしの GET /villagers、update は PUT/PATCH、destroy は DELETE が標準。GETで詳細を見るだけでは更新・削除しない。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-read-route","kind":"choice","options":["index：全員の一覧を表示する","show：id=2 の詳細を表示する","update：id=2 の住所を保存する","destroy：id=2 を削除する"],"prompt":"Route::resource を登録済み。GET /villagers/2 を受け取る組み合わせは？","reveal":"show：id=2 の詳細を表示する","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'resource-read-route' AND payload_json = '{"answer":1,"code":"Route::resource(''villagers'', VillagerController::class);","difficulty":"intermediate","explanation":"GET /villagers/2 は show。index は番号なしの GET /villagers、update は PUT/PATCH、destroy は DELETE が標準。GETで詳細を見るだけでは更新・削除しない。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-read-route","kind":"choice","options":["index：全員の一覧を表示する","show：id=2 の詳細を表示する","update：id=2 の住所を保存する","destroy：id=2 を削除する"],"prompt":"Route::resource を登録済み。GET /villagers/2 を受け取る組み合わせは？","reveal":"show：id=2 の詳細を表示する","topic":"laravel"}');
