INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'resource-update-redirect', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'resource-update-redirect'), 0) + 1, '{"answer":1,"code":"$villager = Villager::findOrFail(2);\n$villager->address = ''北通り'';\nreturn redirect(''/villagers'');","difficulty":"intermediate","explanation":"addressへの代入は手元のモデルだけを変える。save を呼んでいないため、redirectで画面が移ってもDBは西通りのまま。redirectは更新・削除・新規登録のどれも実行しない。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-update-redirect","kind":"choice","options":["北通りに保存されている","西通りのまま","オルの行が削除されている","北通りの新規行が1行増えている"],"prompt":"この処理が終わり一覧へ移動した。DBのオルの住所は？","reveal":"西通りのまま","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'resource-update-redirect' AND payload_json = '{"answer":1,"code":"$villager = Villager::findOrFail(2);\n$villager->address = ''北通り'';\nreturn redirect(''/villagers'');","difficulty":"intermediate","explanation":"addressへの代入は手元のモデルだけを変える。save を呼んでいないため、redirectで画面が移ってもDBは西通りのまま。redirectは更新・削除・新規登録のどれも実行しない。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-update-redirect","kind":"choice","options":["北通りに保存されている","西通りのまま","オルの行が削除されている","北通りの新規行が1行増えている"],"prompt":"この処理が終わり一覧へ移動した。DBのオルの住所は？","reveal":"西通りのまま","topic":"laravel"}');
