INSERT INTO question_revisions (question_id, revision, payload_json) SELECT 'resource-update-transfer', COALESCE((SELECT MAX(revision) FROM question_revisions WHERE question_id = 'resource-update-transfer'), 0) + 1, '{"answer":3,"code":"$material = Material::findOrFail(42);\n$material->stock = 5;\n$material->save();","difficulty":"intermediate","explanation":"id=42 の既存モデルを取得してstockだけを変更・保存するので、赤い鉱石だけ5になる。全行更新でも、新しいモデルの追加でも、削除でもない。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-update-transfer","kind":"choice","options":["両方の鉱石が5で、2行のまま","赤い鉱石の行を追加して3行になる","赤い鉱石が削除され1行になる","青い鉱石は6、赤い鉱石は5で、2行のまま"],"prompt":"PATCH /materials/42 の更新処理。保存後の在庫は？","reveal":"青い鉱石は6、赤い鉱石は5で、2行のまま","topic":"laravel"}' WHERE NOT EXISTS (SELECT 1 FROM question_revisions WHERE question_id = 'resource-update-transfer' AND payload_json = '{"answer":3,"code":"$material = Material::findOrFail(42);\n$material->stock = 5;\n$material->save();","difficulty":"intermediate","explanation":"id=42 の既存モデルを取得してstockだけを変更・保存するので、赤い鉱石だけ5になる。全行更新でも、新しいモデルの追加でも、削除でもない。","filename":"Laravel / コントローラとルートの抜粋","id":"resource-update-transfer","kind":"choice","options":["両方の鉱石が5で、2行のまま","赤い鉱石の行を追加して3行になる","赤い鉱石が削除され1行になる","青い鉱石は6、赤い鉱石は5で、2行のまま"],"prompt":"PATCH /materials/42 の更新処理。保存後の在庫は？","reveal":"青い鉱石は6、赤い鉱石は5で、2行のまま","topic":"laravel"}');
